//! Go's legacy `math/rand` (Go 1 API).
//!
//! [`RngSource::new`] is Go's additive lagged Fibonacci generator: the same seed
//! yields exactly the sequences of Go's `rand.New(rand.NewSource(seed))`,
//! including v1's older `Int31n`, `Float64` and ziggurat algorithms, which
//! differ from [`super::Rand`]. Go's `int` maps to `i64`.
//!
//! ```
//! use rust_stdlib::math::rand::v1::{RngSource, Rand};
//! let mut r = Rand::new(RngSource::new(1));
//! assert_eq!(r.int63(), 5577006791947779410);
//! ```
//!
//! This is not a cryptographically secure generator. The top-level functions
//! use the OS-seeded [`super::GlobalSource`]; as in Go 1.24 and later, there
//! is no global `Seed`.

use super::tables::RNG_COOKED;
use super::zipf::Core;
use super::{exp_step, norm_step, GlobalSource, Source as _};
use std::io;

const RNG_LEN: usize = 607;
const RNG_TAP: usize = 273;
const RNG_MASK: u64 = (1 << 63) - 1;
const INT32_MAX: i64 = (1 << 31) - 1;

/// Go's `rand.Source` (with the optional `Source64` method folded in).
pub trait Source {
    /// A non-negative 63-bit value.
    fn int63(&mut self) -> i64;

    /// Reset the source to the deterministic state for `seed`.
    fn seed(&mut self, seed: i64);

    /// A 64-bit value. Go's `Source64` sources override this; otherwise Go's
    /// `Rand.Uint64` composes two `Int63` values exactly as this default does.
    fn uint64(&mut self) -> u64 {
        let low = (self.int63() as u64) >> 31;
        let high = (self.int63() as u64) << 32;
        low | high
    }
}

impl<S: Source + ?Sized> Source for &mut S {
    fn int63(&mut self) -> i64 {
        (**self).int63()
    }
    fn seed(&mut self, seed: i64) {
        (**self).seed(seed)
    }
    fn uint64(&mut self) -> u64 {
        (**self).uint64()
    }
}

impl<S: Source + ?Sized> Source for Box<S> {
    fn int63(&mut self) -> i64 {
        (**self).int63()
    }
    fn seed(&mut self, seed: i64) {
        (**self).seed(seed)
    }
    fn uint64(&mut self) -> u64 {
        (**self).uint64()
    }
}

/// Go's `rngSource`, the generator returned by `rand.NewSource`: an additive
/// lagged Fibonacci generator (lags 607 and 273) by D. P. Mitchell and
/// J. A. Reeds, seeded through Park-Miller and Go's precomputed `rngCooked`.
#[derive(Clone, PartialEq, Eq)]
pub struct RngSource {
    tap: usize,
    feed: usize,
    vec: Box<[i64; RNG_LEN]>,
}

impl std::fmt::Debug for RngSource {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("RngSource").finish_non_exhaustive()
    }
}

/// Park-Miller minimal standard step, x[n+1] = 48271 * x[n] mod (2**31 - 1).
fn seedrand(x: i32) -> i32 {
    const A: i32 = 48271;
    const Q: i32 = 44488;
    const R: i32 = 3399;
    let hi = x / Q;
    let lo = x % Q;
    let mut x = A.wrapping_mul(lo).wrapping_sub(R.wrapping_mul(hi));
    if x < 0 {
        x = x.wrapping_add(INT32_MAX as i32);
    }
    x
}

impl RngSource {
    /// Equivalent to Go's `rand.NewSource(seed)`.
    pub fn new(seed: i64) -> Self {
        let mut source = Self {
            tap: 0,
            feed: 0,
            vec: Box::new([0; RNG_LEN]),
        };
        source.seed(seed);
        source
    }
}

impl Source for RngSource {
    fn int63(&mut self) -> i64 {
        (self.uint64() & RNG_MASK) as i64
    }

    fn seed(&mut self, seed: i64) {
        self.tap = 0;
        self.feed = RNG_LEN - RNG_TAP;
        let mut seed = seed % INT32_MAX;
        if seed < 0 {
            seed += INT32_MAX;
        }
        if seed == 0 {
            seed = 89482311;
        }
        let mut x = seed as i32;
        for i in -20..RNG_LEN as isize {
            x = seedrand(x);
            if i >= 0 {
                let mut u = i64::from(x) << 40;
                x = seedrand(x);
                u ^= i64::from(x) << 20;
                x = seedrand(x);
                u ^= i64::from(x);
                u ^= RNG_COOKED[i as usize];
                self.vec[i as usize] = u;
            }
        }
    }

    fn uint64(&mut self) -> u64 {
        self.tap = if self.tap == 0 {
            RNG_LEN - 1
        } else {
            self.tap - 1
        };
        self.feed = if self.feed == 0 {
            RNG_LEN - 1
        } else {
            self.feed - 1
        };
        let x = self.vec[self.feed].wrapping_add(self.vec[self.tap]);
        self.vec[self.feed] = x;
        x as u64
    }
}

/// Go's `rand.Rand` (v1). Implements [`io::Read`] with Go's semantics.
///
/// Methods that take a bound panic, as Go does, when the bound is not
/// positive.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Rand<S> {
    src: S,
    read_val: i64,
    read_pos: i8,
}

impl<S: Source> Rand<S> {
    /// Go's `rand.New(src)`.
    pub fn new(src: S) -> Self {
        Self {
            src,
            read_val: 0,
            read_pos: 0,
        }
    }

    /// Borrow the underlying source.
    pub fn source(&self) -> &S {
        &self.src
    }

    /// Return the underlying source.
    pub fn into_source(self) -> S {
        self.src
    }

    /// Reseed the source and discard bytes buffered by [`io::Read`].
    pub fn seed(&mut self, seed: i64) {
        self.src.seed(seed);
        self.read_pos = 0;
    }

    /// A non-negative 63-bit integer.
    pub fn int63(&mut self) -> i64 {
        self.src.int63()
    }

    /// A 32-bit value.
    pub fn uint32(&mut self) -> u32 {
        (self.int63() >> 31) as u32
    }

    /// A 64-bit value.
    pub fn uint64(&mut self) -> u64 {
        self.src.uint64()
    }

    /// A non-negative 31-bit integer.
    pub fn int31(&mut self) -> i32 {
        (self.int63() >> 32) as i32
    }

    /// Go's `Int`: a non-negative integer (Go's 64-bit `int`).
    pub fn int(&mut self) -> i64 {
        ((self.int63() as u64) << 1 >> 1) as i64
    }

    /// A value in `[0, n)` by rejection sampling and modulo.
    ///
    /// # Panics
    /// If `n <= 0`.
    pub fn int63n(&mut self, n: i64) -> i64 {
        if n <= 0 {
            panic!("invalid argument to Int63n");
        }
        if n & (n - 1) == 0 {
            return self.int63() & (n - 1);
        }
        let max = ((1u64 << 63) - 1 - (1u64 << 63) % n as u64) as i64;
        let mut v = self.int63();
        while v > max {
            v = self.int63();
        }
        v % n
    }

    /// A value in `[0, n)` by rejection sampling and modulo.
    ///
    /// # Panics
    /// If `n <= 0`.
    pub fn int31n(&mut self, n: i32) -> i32 {
        if n <= 0 {
            panic!("invalid argument to Int31n");
        }
        if n & (n - 1) == 0 {
            return self.int31() & (n - 1);
        }
        let max = ((1u32 << 31) - 1 - (1u32 << 31) % n as u32) as i32;
        let mut v = self.int31();
        while v > max {
            v = self.int31();
        }
        v % n
    }

    /// Go's private `int31n`: Lemire's method on `Uint32`, used only by
    /// `Shuffle` to keep `Int31n`'s historical stream unchanged.
    fn int31n_lemire(&mut self, n: i32) -> i32 {
        let mut v = self.uint32();
        let mut prod = u64::from(v) * n as u64;
        let mut low = prod as u32;
        if low < n as u32 {
            let thresh = (n.wrapping_neg() as u32) % n as u32;
            while low < thresh {
                v = self.uint32();
                prod = u64::from(v) * n as u64;
                low = prod as u32;
            }
        }
        (prod >> 32) as i32
    }

    /// Go's `Intn`: `Int31n` for bounds that fit, otherwise `Int63n`.
    ///
    /// # Panics
    /// If `n <= 0`.
    pub fn intn(&mut self, n: i64) -> i64 {
        if n <= 0 {
            panic!("invalid argument to Intn");
        }
        if n <= INT32_MAX {
            return i64::from(self.int31n(n as i32));
        }
        self.int63n(n)
    }

    /// A value in `[0.0, 1.0)`, resampling the rare rounding to 1.0.
    pub fn float64(&mut self) -> f64 {
        loop {
            let f = self.int63() as f64 / (1u64 << 63) as f64;
            if f != 1.0 {
                return f;
            }
        }
    }

    /// A value in `[0.0, 1.0)`, resampling the rare rounding to 1.0.
    pub fn float32(&mut self) -> f32 {
        loop {
            let f = self.float64() as f32;
            if f != 1.0 {
                return f;
            }
        }
    }

    /// A pseudo-random permutation of `0..n` (Go's inside-out algorithm).
    pub fn perm(&mut self, n: usize) -> Vec<usize> {
        let mut m = vec![0; n];
        for i in 0..n {
            let j = self.intn(i as i64 + 1) as usize;
            m[i] = m[j];
            m[j] = i;
        }
        m
    }

    /// Fisher-Yates shuffle of `n` elements through `swap(i, j)`.
    pub fn shuffle<F: FnMut(usize, usize)>(&mut self, n: usize, mut swap: F) {
        let mut i = n as i64 - 1;
        while i > INT32_MAX - 1 {
            let j = self.int63n(i + 1) as usize;
            swap(i as usize, j);
            i -= 1;
        }
        while i > 0 {
            let j = self.int31n_lemire(i as i32 + 1) as usize;
            swap(i as usize, j);
            i -= 1;
        }
    }

    /// A standard normal value using v1's ziggurat over `Uint32`.
    pub fn norm_float64(&mut self) -> f64 {
        loop {
            let j = self.uint32() as i32; // possibly negative
            let i = (j & 0x7f) as usize;
            if let Some(value) = norm_step(j, i, &mut || self.float64()) {
                return value;
            }
        }
    }

    /// An exponential value with rate 1 using v1's ziggurat over `Uint32`.
    pub fn exp_float64(&mut self) -> f64 {
        loop {
            let j = self.uint32();
            let i = (j & 0xff) as usize;
            if let Some(value) = exp_step(j, i, &mut || self.float64()) {
                return value;
            }
        }
    }
}

/// Go's `rand.Zipf` (v1): Zipf-distributed values drawn from a [`Rand`].
#[derive(Debug)]
pub struct Zipf<'a, S> {
    r: &'a mut Rand<S>,
    core: Core,
}

impl<'a, S: Source> Zipf<'a, S> {
    /// Go's `rand.NewZipf`: values `k` in `[0, imax]` with P(k) proportional
    /// to `(v + k) ** (-s)`. Requires `s > 1` and `v >= 1`; `None` otherwise.
    pub fn new(r: &'a mut Rand<S>, s: f64, v: f64, imax: u64) -> Option<Self> {
        Some(Self {
            r,
            core: Core::new(s, v, imax)?,
        })
    }

    /// Go's `Zipf.Uint64`: the next value of the distribution.
    pub fn uint64(&mut self) -> u64 {
        let r = &mut *self.r;
        self.core.sample(|| r.float64())
    }
}

/// Go's `Rand.Read`: seven bytes per `Int63`, least significant first, with
/// leftovers carried to the next call. Always fills the whole buffer.
impl<S: Source> io::Read for Rand<S> {
    fn read(&mut self, p: &mut [u8]) -> io::Result<usize> {
        let mut pos = self.read_pos;
        let mut val = self.read_val;
        for byte in p.iter_mut() {
            if pos == 0 {
                val = self.src.int63();
                pos = 7;
            }
            *byte = val as u8;
            val >>= 8;
            pos -= 1;
        }
        self.read_pos = pos;
        self.read_val = val;
        Ok(p.len())
    }
}

/// Go's `runtimeSource` for the v1 top-level functions.
#[derive(Debug, Clone, Copy)]
struct Global;

impl Source for Global {
    fn int63(&mut self) -> i64 {
        (GlobalSource.uint64() & RNG_MASK) as i64
    }
    fn seed(&mut self, _seed: i64) {
        // Unreachable through this module's API; Go's global Seed is a no-op.
    }
    fn uint64(&mut self) -> u64 {
        GlobalSource.uint64()
    }
}

fn global() -> Rand<Global> {
    Rand::new(Global)
}

/// Go's top-level `Int63` from the OS-seeded [`GlobalSource`].
pub fn int63() -> i64 {
    global().int63()
}

/// Go's top-level `Uint32`.
pub fn uint32() -> u32 {
    global().uint32()
}

/// Go's top-level `Uint64`.
pub fn uint64() -> u64 {
    global().uint64()
}

/// Go's top-level `Int31`.
pub fn int31() -> i32 {
    global().int31()
}

/// Go's top-level `Int`.
pub fn int() -> i64 {
    global().int()
}

/// Go's top-level `Int63n`. Panics if `n <= 0`.
pub fn int63n(n: i64) -> i64 {
    global().int63n(n)
}

/// Go's top-level `Int31n`. Panics if `n <= 0`.
pub fn int31n(n: i32) -> i32 {
    global().int31n(n)
}

/// Go's top-level `Intn`. Panics if `n <= 0`.
pub fn intn(n: i64) -> i64 {
    global().intn(n)
}

/// Go's top-level `Float64`.
pub fn float64() -> f64 {
    global().float64()
}

/// Go's top-level `Float32`.
pub fn float32() -> f32 {
    global().float32()
}

/// Go's top-level `Perm`.
pub fn perm(n: usize) -> Vec<usize> {
    global().perm(n)
}

/// Go's top-level `Shuffle`. `swap` may itself call these functions.
pub fn shuffle<F: FnMut(usize, usize)>(n: usize, swap: F) {
    global().shuffle(n, swap)
}

/// Go's top-level `Read`: fill `p` with unseeded random bytes.
pub fn read(p: &mut [u8]) -> io::Result<usize> {
    io::Read::read(&mut global(), p)
}

/// Go's top-level `Seed`. Since Go 1.24 it does nothing unless the
/// `GODEBUG=randseednop=0` setting is given, which this port does not read.
pub fn seed(_seed: i64) {}

/// Go's top-level `NormFloat64`.
pub fn norm_float64() -> f64 {
    global().norm_float64()
}

/// Go's top-level `ExpFloat64`.
pub fn exp_float64() -> f64 {
    global().exp_float64()
}
